import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';

const CreateProduct = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [photos, setPhotos] = useState([]);
    const [photoPreviews, setPhotoPreviews] = useState([]);
    const [formData, setFormData] = useState({
        title: '',
        description: '',
        price: '',
        category: 'telemovel',
        condition: 'semi-novo',
        location: 'Luanda',
        contactMethod: 'whatsapp',
        contactNumber: '',
        contactHours: ''
    });

    // Verificar se é vendedor
    if (!user || user.type !== 'vendedor') {
        return (
            <div className="max-w-md mx-auto bg-white rounded-xl shadow-md p-8 text-center">
                <h2 className="text-2xl font-bold text-red-600 mb-4">Acesso Negado</h2>
                <p className="text-gray-600 mb-4">Apenas vendedores podem criar anúncios.</p>
                <a href="/register" className="text-primary-600 hover:underline">Cadastre-se como vendedor</a>
            </div>
        );
    }

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handlePhotoChange = (e) => {
        const files = Array.from(e.target.files);
        
        if (photos.length + files.length > 5) {
            toast.error('Máximo de 5 fotos');
            return;
        }
        
        setPhotos([...photos, ...files]);
        
        files.forEach(file => {
            const reader = new FileReader();
            reader.onload = (ev) => {
                setPhotoPreviews(prev => [...prev, ev.target.result]);
            };
            reader.readAsDataURL(file);
        });
    };

    const removePhoto = (index) => {
        setPhotos(photos.filter((_, i) => i !== index));
        setPhotoPreviews(photoPreviews.filter((_, i) => i !== index));
    };

    const setMainPhoto = (index) => {
        const photo = photos.splice(index, 1)[0];
        const preview = photoPreviews.splice(index, 1)[0];
        setPhotos([photo, ...photos]);
        setPhotoPreviews([preview, ...photoPreviews]);
        toast.success('Foto principal alterada!');
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (!formData.title || !formData.description || !formData.price || !formData.contactNumber) {
            toast.error('Preencha todos os campos obrigatórios');
            return;
        }
        
        setLoading(true);
        
        const form = new FormData();
        form.append('title', formData.title);
        form.append('description', formData.description);
        form.append('price', formData.price);
        form.append('category', formData.category);
        form.append('condition', formData.condition);
        form.append('location', formData.location);
        form.append('contactMethod', formData.contactMethod);
        form.append('contactNumber', formData.contactNumber);
        form.append('contactHours', formData.contactHours);
        
        photos.forEach(photo => {
            form.append('photos', photo);
        });
        
        try {
            const response = await api.post('/products', form, {
                headers: { 'Content-Type': 'multipart/form-data' }
            });
            
            if (response.data.success) {
                toast.success('Anúncio criado com sucesso!');
                navigate('/seller/dashboard');
            }
        } catch (error) {
            toast.error(error.response?.data?.error || 'Erro ao criar anúncio');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="max-w-2xl mx-auto">
            <div className="bg-white rounded-xl shadow-md p-6">
                <h1 className="text-2xl font-bold mb-6">Anunciar Produto</h1>
                
                <form onSubmit={handleSubmit} className="space-y-4">
                    {/* Título */}
                    <div>
                        <label className="block text-gray-700 mb-1">Título *</label>
                        <input
                            type="text"
                            name="title"
                            value={formData.title}
                            onChange={handleChange}
                            placeholder="Ex: iPhone 12 128GB"
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600 focus:ring-1 focus:ring-primary-600"
                            required
                        />
                    </div>
                    
                    {/* Descrição */}
                    <div>
                        <label className="block text-gray-700 mb-1">Descrição *</label>
                        <textarea
                            name="description"
                            value={formData.description}
                            onChange={handleChange}
                            rows="4"
                            placeholder="Descreva o produto, estado de conservação, acessórios incluídos..."
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600 focus:ring-1 focus:ring-primary-600"
                            required
                        />
                    </div>
                    
                    {/* Preço e Categoria */}
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-gray-700 mb-1">Preço (Kz) *</label>
                            <input
                                type="number"
                                name="price"
                                value={formData.price}
                                onChange={handleChange}
                                placeholder="150000"
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-gray-700 mb-1">Categoria</label>
                            <select
                                name="category"
                                value={formData.category}
                                onChange={handleChange}
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                            >
                                <option value="telemovel">Telemóvel</option>
                                <option value="laptop">Laptop</option>
                                <option value="console">Console</option>
                                <option value="tablet">Tablet</option>
                            </select>
                        </div>
                    </div>
                    
                    {/* Estado e Localização */}
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-gray-700 mb-1">Estado</label>
                            <select
                                name="condition"
                                value={formData.condition}
                                onChange={handleChange}
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                            >
                                <option value="novo">Novo</option>
                                <option value="semi-novo">Semi-novo</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-gray-700 mb-1">Localização</label>
                            <input
                                type="text"
                                name="location"
                                value={formData.location}
                                onChange={handleChange}
                                placeholder="Luanda, Talatona..."
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-primary-600"
                            />
                        </div>
                    </div>
                    
                    {/* Fotos */}
                    <div>
                        <label className="block text-gray-700 mb-1">Fotos (máx 5)</label>
                        <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:border-primary-600 transition cursor-pointer"
                             onClick={() => document.getElementById('photoInput').click()}>
                            <p className="text-gray-500">📸 Clique para adicionar fotos</p>
                            <p className="text-xs text-gray-400 mt-1">A primeira foto será a principal</p>
                        </div>
                        <input
                            type="file"
                            id="photoInput"
                            accept="image/*"
                            multiple
                            onChange={handlePhotoChange}
                            className="hidden"
                        />
                        
                        {photoPreviews.length > 0 && (
                            <div className="flex gap-2 mt-3 flex-wrap">
                                {photoPreviews.map((preview, idx) => (
                                    <div key={idx} className="relative group">
                                        <img 
                                            src={preview} 
                                            alt={`Preview ${idx + 1}`} 
                                            className={`w-20 h-20 object-cover rounded-lg border-2 ${idx === 0 ? 'border-primary-600' : 'border-gray-200'}`}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => removePhoto(idx)}
                                            className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs hover:bg-red-600"
                                        >
                                            ×
                                        </button>
                                        {idx !== 0 && (
                                            <button
                                                type="button"
                                                onClick={() => setMainPhoto(idx)}
                                                className="absolute bottom-0 left-0 right-0 bg-black bg-opacity-50 text-white text-xs py-1 rounded-b-lg opacity-0 group-hover:opacity-100 transition"
                                            >
                                                Principal
                                            </button>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}
                        {photoPreviews.length === 0 && (
                            <p className="text-xs text-gray-400 mt-2">Nenhuma foto adicionada</p>
                        )}
                    </div>
                    
                    {/* Contato */}
                    <div className="border-t pt-4 mt-2">
                        <h3 className="font-semibold text-gray-700 mb-3">📞 Como prefere ser contactado?</h3>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-gray-700 mb-1">Método</label>
                                <select
                                    name="contactMethod"
                                    value={formData.contactMethod}
                                    onChange={handleChange}
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                                >
                                    <option value="whatsapp">WhatsApp</option>
                                    <option value="call">Ligação</option>
                                    <option value="both">Ambos</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-gray-700 mb-1">Número *</label>
                                <input
                                    type="tel"
                                    name="contactNumber"
                                    value={formData.contactNumber}
                                    onChange={handleChange}
                                    placeholder="923 456 789"
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                                    required
                                />
                            </div>
                        </div>
                        <div className="mt-2">
                            <label className="block text-gray-700 mb-1">Horário preferido</label>
                            <input
                                type="text"
                                name="contactHours"
                                value={formData.contactHours}
                                onChange={handleChange}
                                placeholder="Ex: 9h às 18h"
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                            />
                        </div>
                    </div>
                    
                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full bg-primary-600 text-white py-3 rounded-lg font-semibold hover:bg-primary-700 transition disabled:opacity-50"
                    >
                        {loading ? 'Publicando...' : 'Publicar Anúncio'}
                    </button>
                </form>
            </div>
        </div>
    );
};

export default CreateProduct;
